def stream_rows(resource, transform):
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            value = transform(row)
            yield value
    except GeneratorExit:
        resource.close()
        raise
    except BaseException:
        try:
            resource.close()
        except Exception:
            pass
        raise
    else:
        resource.close()
E
cat > src/consumer.py <<'E'
from .service import stream_rows


def take(resource, transform, limit):
    if limit <= 0:
        return []
    stream = stream_rows(resource, transform)
    result = []
    try:
        for row in stream:
            result.append(row)
            if len(result) >= limit:
                break
    except BaseException:
        try:
            stream.close()
        except Exception:
            pass
        raise
    stream.close()
    return result
E
